export default class ContactModal {
  constructor(element) {
    this.element = element;
    console.log(element);
    this.openButton = document.querySelector('.modalopen');
    console.log(this.openButton);
    this.closeButton = this.element.querySelector('.modalclose');
    console.log(this.closeButton);
    this.init();
  }

  init() {
    this.openButton.addEventListener('click', this.openModal.bind(this));
    this.closeButton.addEventListener('click', this.closeModal.bind(this));
  }

  openModal() {
    console.log('Open modal');
    this.element.classList.remove('modalhidden');
  }

  closeModal() {
    console.log('Close modal');
    this.element.classList.add('modalhidden');
  }
}
