import Swiper from 'swiper/bundle';
export default class Carousel {
  constructor(element) {
    this.element = element;
    this.options = {
      slidesPerView: 1,
      spaceBetween: 0,
      centeredSlides: true,

      pagination: {
        el: this.element.querySelector('.swiper-pagination'),
      },
      navigation: {
        nextEl: this.element.querySelector('.swiper-button-next'),
        prevEl: this.element.querySelector('.swiper-button-prev'),
      },
    };

    this.init();
  }
  setOption() {
    if ('split' in this.element.dataset) {
      this.options.breakpoints = {
        768: {
          slidesPerView: 1,
        },
      };
    }

    if ('autoplay' in this.element.dataset) {
      this.options.autoplay = {
        delay: 2000,
        pauseOnMouseEnter: false,
        disableOnInteraction: false,
      };
    }
    if ('loop' in this.element.dataset) {
      this.options.loop = {
        loop: true,
      };
    }
    if ('slide' in this.element.dataset) {
      this.options.slidesPerView = parseFloat(this.element.dataset.slide, 10);
    }

    if ('news' in this.element.dataset) {
      this.options.slidesPerView = 1;
      this.options.spaceBetween = 30;
      this.options.breakpoints = {
        540: {
          slidesPerView: 1.5,
        },
        1000: {
          slidesPerView: 2.5,
        },
        1400: {
          slidesPerView: 3.5,
        },
      };
    }
  }
  init() {
    this.setOption();
    const swiper = new Swiper(this.element, this.options);
  }
}
